#!/usr/bin/env python3
# In a notebook, do not edit this file. It is generic - the template's, listed
# in .claude/notebook/manifest.txt - and the update skill replaces it; the
# notebook's pre-commit hook refuses a commit that changes it. To extend:
#   - a setting or an audit rule: .scripts/notebook_config.py
#   - an operation or a check of the notebook's own: a script of its own in
#     .scripts/ that imports this one, never a copy of it
#   - a rule for one type: that type's declaration in Types/
#   - a fix every notebook needs: ask the template for it, with an issue -
#     .claude/notebook/requests.md
# The whole table: .claude/notebook/upstream.md, "The outlets".
"""Audit the notes, by category.

The question each check asks is "does this page stand on its own?", because
every page is read on its own. Pages can point at structures that no longer
exist, or hold provenance but no content.

  audit.py                 every category
  audit.py <Folder> ...    only those
  audit.py --verbose       list every offending page, not just the counts

Link facts come from the running Obsidian app when it is reachable, since
it is authoritative about its own graph; otherwise they are skipped rather
than guessed. Always exits 0: the counts are a browse, not a defect list.
"""

import json
import os
import pathlib
import re
import shutil
import subprocess
import sys

import os

# `python3 -I` isolates sys.path, which drops this script's own directory -
# so the config beside it is not importable without putting it back.
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import notebook_config
import notebook

# Derived from this file's location, never hardcoded: a hardcoded path lets
# a script run from one vault quietly read or edit another.
VAULT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
NOTES = VAULT  # the notes are the vault root

# Derived, not listed: any folder holding pages with a `type:`. Hardcoding it
# meant a promoted type was audited by nobody until someone remembered to add
# it here - see .claude/notebook/promotion.md. The ledger is excluded on purpose:
# it is the ledger, and "does this page stand on its own" is the wrong question
# to ask of a log (.claude/notebook/ledger.md).
NOT_AUDITED = notebook.machinery()

def _categories():
    out = set()
    for p in pathlib.Path(NOTES).glob("*/*.md"):
        if p.parent.name in NOT_AUDITED:
            continue
        head = p.read_text(encoding="utf-8", errors="replace")[:400]
        if re.match(r"---\n(?:.*\n)*?type:", head):
            out.add(p.parent.name)
    return sorted(out)

def _nested():
    """Pages a scan one folder deep misses: an entity that became a folder,
    and every page an owner holds, at any depth (graph.md, "Ownership").
    Grouped by their type's folder, and never machinery wherever it sits."""
    reg, out = notebook.registry(), {}
    for t, p in notebook.pages():
        parts = p.relative_to(NOTES).parts
        # Machinery by its own type here, not by a folder above it: a page a
        # ledger entry owns sits inside the ledger's folder and is no log.
        if len(parts) > 2 and t in reg and parts[0] not in NOT_AUDITED \
                and not (reg[t]["ledger"] or reg[t]["generated"] == "true"):
            out.setdefault(reg[t]["folder"], []).append(p)
    return out

NESTED = _nested()
CATEGORIES = sorted(set(_categories()) | set(NESTED))

def _files(cat):
    folder = os.path.join(NOTES, cat)
    top = [os.path.join(folder, f) for f in os.listdir(folder)] if os.path.isdir(folder) else []
    return sorted([f for f in top if f.endswith(".md")] + [str(p) for p in NESTED.get(cat, [])],
                  key=os.path.basename)

# Pages that are documentation of the notes themselves, not notes.
SKIP = notebook_config.NOT_OURS | {notebook_config.HUB}

# Wording that points at something instead of saying it.
DEFERRAL = re.compile(
    r"(is|are) (in|on) the [A-Z][\w' ]+ table"
    r"|(recorded|scattered|noted) (elsewhere|around|as)"
    r"|is on that [\w' ]+'s own page"
    r"|see the [A-Z][\w' ]+ table"
    + "".join("|" + d for d in notebook_config.AUDIT_DEFERRALS),
    re.I)

OBSIDIAN = shutil.which("obsidian")


def app_is_this_vault():
    """Whether the running app's vault of this folder's name is this folder.
    The CLI finds a vault by its name alone, so a clone or a second checkout
    with the same folder name would otherwise be answered - or written to -
    by the other one."""
    global _THIS_VAULT
    if _THIS_VAULT is None:
        try:
            r = subprocess.run([OBSIDIAN, f"vault={os.path.basename(VAULT)}", "eval",
                                "code=app.vault.adapter.basePath"],
                               capture_output=True, text=True, timeout=20)
            out = r.stdout.strip()
            _THIS_VAULT = (r.returncode == 0 and out.startswith("=>")
                           and os.path.realpath(out[2:].strip()) == os.path.realpath(VAULT))
        except (OSError, subprocess.SubprocessError):
            _THIS_VAULT = False
    return _THIS_VAULT

_THIS_VAULT = None

THIN_WORDS = 25          # a page with less body than this is barely a note
WIKILINK = re.compile(r"\[\[(.+?)\]\]", re.S)


def link_target(inner):
    """The page a wikilink points at. Explicit parsing - the escaped pipe in
    a table cell, [[Target\\|label]], defeats the obvious regex."""
    for sep in ("\\|", "|"):
        if sep in inner:
            inner = inner.split(sep, 1)[0]
            break
    return inner.rstrip("\\").split("#", 1)[0].strip()


def body_of(text):
    """Everything after the frontmatter and the H1."""
    t = re.sub(r"^---\n.*?\n---\n", "", text, flags=re.S)
    return re.sub(r"^#\s+.*$", "", t, count=1, flags=re.M)


def obsidian_links():
    """(resolved, unresolved) maps from the running app, or (None, None)."""
    if not OBSIDIAN or not app_is_this_vault():
        return None, None
    try:
        r = subprocess.run(
            [OBSIDIAN, f"vault={os.path.basename(VAULT)}", "eval",
             "code=JSON.stringify({r:app.metadataCache.resolvedLinks,"
             "u:app.metadataCache.unresolvedLinks})"],
            capture_output=True, text=True, timeout=30)
    except (subprocess.TimeoutExpired, OSError):
        return None, None
    out = r.stdout.strip()
    if r.returncode != 0 or not out.startswith("=>"):
        return None, None
    try:
        d = json.loads(out[2:].strip())
    except ValueError:
        return None, None
    return d.get("r", {}), d.get("u", {})


def main():
    args = [a for a in sys.argv[1:] if not a.startswith("-")]
    verbose = "--verbose" in sys.argv or "-v" in sys.argv
    wanted = [c for c in CATEGORIES if c.lower() in {a.lower() for a in args}] or CATEGORIES

    resolved, _ = obsidian_links()
    inbound = {}
    if resolved is not None:
        for src, dests in resolved.items():
            for dest in dests:
                inbound[dest] = inbound.get(dest, 0) + 1

    findings = {}
    for cat in wanted:
        rows = []
        for full in _files(cat):
            f = os.path.basename(full)
            if f in SKIP:
                continue
            rel = os.path.relpath(full, VAULT)
            text = open(full, encoding="utf-8").read()
            body = body_of(text)
            problems = []

            if len(body.split()) < THIN_WORDS:
                problems.append(f"thin ({len(body.split())} words)")

            for m in DEFERRAL.finditer(text):
                problems.append(f'defers: "{m.group(0).strip()[:44]}"')

            problems += notebook_config.audit_page(cat, text)

            out_links = {link_target(m.group(1)) for m in WIKILINK.finditer(text)}
            out_links = {l for l in out_links if l and not l.startswith(notebook_config.HUB[:-3])}
            if resolved is not None:
                n_in = inbound.get(rel.replace(os.sep, "/"), 0)
                if not out_links and not n_in:
                    problems.append("disconnected (no links out, none in)")
                elif not n_in:
                    problems.append("nothing links here")

            if problems:
                rows.append((f[:-3], problems))
        if rows:
            findings[cat] = rows

    if resolved is None:
        print("note: Obsidian did not answer for this vault, so link checks were skipped\n")

    total = 0
    for cat in wanted:
        rows = findings.get(cat, [])
        n = len(_files(cat))
        if not rows:
            print(f"{cat:<10} {n:>3} pages   clean")
            continue
        total += len(rows)
        print(f"{cat:<10} {n:>3} pages   {len(rows)} to look at")
        kinds = {}
        for _, probs in rows:
            for p in probs:
                kinds[p.split("(")[0].split(":")[0].strip()] = \
                    kinds.get(p.split("(")[0].split(":")[0].strip(), 0) + 1
        for k, c in sorted(kinds.items(), key=lambda kv: -kv[1]):
            print(f"              {c:>3}  {k}")
        if verbose:
            for name, probs in rows:
                print(f"                - {name}")
                for p in probs:
                    print(f"                    {p}")
    print(f"\n{total} pages flagged across {len(wanted)} categories")
    # Always 0. These counts are a browse, not a defect list (contract.md law 7):
    # a thin page is usually thin because little is known yet. Exiting 1 here
    # told anything gating on it that the notebook was broken when it was not.
    return 0


if __name__ == "__main__":
    sys.exit(main())
